UPDATE orbit_analysis_daily_quota SET admitted_count=admitted_count+1 WHERE
tenant_id=#{job.tenantId} AND rule_id=#{job.ruleId} AND entity_id=#{job.entityId} AND
business_date=#{job.businessDate} AND admitted_count < #{maximum}

UPDATE orbit_analysis_gate SET generation=#{job.generation},last_admitted_at=#{job.createdAt}
WHERE tenant_id=#{job.tenantId} AND rule_id=#{job.ruleId} AND entity_id=#{job.entityId} AND
generation=#{job.generation}-1
